// 27-tap direct-form FIR, 8-bit samples, PIPELINED: products registered in
// stage 1, summed in stage 2 -> shorter register-to-register path, higher Fmax.
// Functionally identical to the reference up to a fixed extra latency.
module firr27_v3 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
);
    reg [7:0] xs [0:26];
    reg [15:0] p [0:26];
    integer i;
    always @(posedge clk) begin
        if (!rst_n) begin
            for (i = 0; i < 27; i = i + 1) begin xs[i] <= 8'd0; p[i] <= 16'd0; end
            y <= 16'd0;
        end else begin
            xs[0] <= x;
            for (i = 1; i < 27; i = i + 1) xs[i] <= xs[i-1];
            p[0] <= 8'd2 * x + 5;
            for (i = 1; i < 27; i = i + 1) p[i] <= 8'd2 * xs[i] + 5;
            y <= p[0] + p[1] + p[2] + p[3] + p[4] + p[5] + p[6] + p[7] + p[8] + p[9] + p[10] + p[11] + p[12] + p[13] + p[14] + p[15] + p[16] + p[17] + p[18] + p[19] + p[20] + p[21] + p[22] + p[23] + p[24] + p[25] + p[26];
        end
    end
endmodule
